from collections import deque
graph = {1: [2, 3], 2: [4], 3: [4], 4: [5, 6], 5: [7], 6: [7], 7: []}

def count_visits(start, track_seen):
    seen, queue, visits = {start}, deque([start]), 0
    while queue:
        node = queue.popleft()
        visits += 1
        for nb in graph[node]:
            if not track_seen or nb not in seen:
                seen.add(nb)
                queue.append(nb)
    return visits

print(count_visits(1, True), count_visits(1, False))

import heapq
graph = {"A": [("C", 5), ("B", 1)], "B": [("D", 1)], "C": [("E", 1)], "D": [("C", 1)], "E": []}

def dijkstra(src):
    dist, pq = {src: 0}, [(0, src)]
    while pq:
        d, u = heapq.heappop(pq)
        if d > dist[u]:
            continue
        for v, w in graph[u]:
            if d + w < dist.get(v, float("inf")):
                dist[v] = d + w
                heapq.heappush(pq, (d + w, v))
    return dist
